#include <srvros/intel_display_hda.h>
#include <assert.h>
#include <stdio.h>
#include <string.h>
struct model {const char *mode;uint64_t t;unsigned maps,reads,guards,ends;bool mapped;};
static bool is(struct model *m,const char *s){return !strcmp(m->mode,s);}
static uint64_t now(void *p){struct model *m=p;if(is(m,"zero"))return 0;if(is(m,"frozen"))return 100;if(is(m,"backward"))return 1000-m->t++;return ++m->t;}
static bool endpoint(void *p,struct intel_hda_endpoint *e){struct model *m=p;m->ends++;*e=(struct intel_hda_endpoint){0x160c8086,0x04030009,0x011b106b,6,1,0,1,0xc1610004,0,true};if(is(m,"d3") || (is(m,"power-change") && m->reads))e->pm=3;if(is(m,"bar"))e->bar+=4096;if(is(m,"id"))e->id^=1;if(is(m,"decode"))e->command=4;if(is(m,"reserved"))e->reserved=false;return true;}
static bool guard(void *p){struct model *m=p;m->guards++;return !is(m,"cache") && !(is(m,"late-cache") && m->guards==3);}
static bool map(void *p){struct model *m=p;m->maps++;if(is(m,"map"))return false;m->mapped=true;if(is(m,"deadline"))m->t+=200001;return true;}
static bool read_reg(void *p,unsigned off,unsigned width,uint32_t *v){struct model *m=p;assert(m->mapped && intel_hda_read_allowed(off,width));m->reads++;*v=0;if(off==0)*v=is(m,"over")?0x9001:is(m,"max")?0x4401:0x1101;if(off==8)*v=1;if(is(m,"float"))*v=(1ull<<(8*width))-1;if(is(m,"active")){if(off==0x80 || off==0x4c || off==0x5c)*v=2;if(off==0x70)*v=0x100001;}if(is(m,"changed") && m->reads>23 && off==0x98)*v=4096;return !is(m,"read");}
static bool unmap(void *p){struct model *m=p;assert(m->mapped);if(is(m,"retire"))return false;m->mapped=false;return true;}
int main(int argc,char **argv){struct model m={.mode=argc>1?argv[1]:"normal",.t=100};struct intel_hda_result r={0};struct intel_hda_io io={&m,endpoint,guard,map,read_reg,unmap,now};bool ok=intel_hda_observe(&r,!is(&m,"admission"),io);bool good=is(&m,"normal") || is(&m,"active") || is(&m,"changed") || is(&m,"max");assert(ok==good);assert(r.complete==good);if(good){assert(r.samples==2 && r.maps==r.retired && !r.retained);assert(r.reads==2*(11+6*r.sample[0].streams));assert(r.run_mask==(is(&m,"active")?1u:0u));assert(r.dma_mask==(is(&m,"active")?7u:0u));assert(r.stable!=is(&m,"changed"));}if(is(&m,"retire"))assert(r.retained && m.mapped);else assert(!m.mapped);if(is(&m,"admission") || is(&m,"d3") || is(&m,"bar") || is(&m,"id") || is(&m,"decode") || is(&m,"reserved") || is(&m,"cache") || is(&m,"zero") || is(&m,"backward"))assert(!m.maps && !m.reads);if(is(&m,"deadline"))assert(!m.reads);unsigned reads=m.reads,guards=m.guards;struct intel_hda_result copy=r;assert(!intel_hda_observe(&r,true,io));assert(!intel_hda_observe(&copy,true,io));assert(m.reads==reads && m.guards==guards);assert(!intel_hda_read_allowed(0x83,1));assert(!intel_hda_read_allowed(0x4d,1));assert(!intel_hda_read_allowed(0x60,4));assert(!intel_hda_read_allowed(0x80,4));assert(!intel_hda_read_allowed(0x82,2));assert(!intel_hda_read_allowed(0x180,2));puts("display-hda-core: PASS bounded read-only census, exact endpoint, topology, dynamic observations, clocks and cleanup");}
